    [Parameter] public bool Readonly { get; set; }

    /// <summary>Raised after a task bar's start/end dates change via drag/resize, with the updated task (design spec Phase 2, T1 — v2-parity <c>OnDateChange</c>, same contract as v2's <c>Gantt.OnDateChange</c>). Also folded into <see cref="TasksChanged"/>.</summary>
    [Parameter] public EventCallback<GanttTask> OnDateChange { get; set; }

    /// <summary>
    /// Unified commit GATE (Phase 4 — the REUI <c>onEventUpdate</c> analog,
    /// upgraded from a Phase 1-3 post-commit notification to a real
    /// pre-commit gate as part of this promotion; see <see
    /// cref="GanttUpdateResult"/>'s own remarks for why this is the ONE
    /// breaking change the promotion ships). Called for EVERY
    /// drag/resize/progress/create edit — <see cref="GanttTaskUpdateSource"/>
    /// discriminates which gesture — BEFORE anything commits to this chart's
    /// state, so a consumer can:
    /// <list type="bullet">
    ///   <item><b>Reject</b> (<see cref="GanttUpdateResult.Reject"/>/<c>false</c>): nothing commits — no state change, no <see cref="OnDateChange"/>/<see cref="OnProgressChange"/>/<see cref="OnTaskCreate"/>, no <see cref="TasksChanged"/>.</item>
    ///   <item><b>Accept</b> (<see cref="GanttUpdateResult.Accept"/>/<c>true</c>): commits exactly the proposed <see cref="GanttTaskUpdate.Task"/> — byte-identical to every Phase 1-3 "no handler wired up" render.</item>
    ///   <item><b>Accept with an adjustment</b> (<see cref="GanttUpdateResult.AcceptWith"/>): commits the proposal with <see cref="GanttUpdateAdjustment.Start"/>/<see cref="GanttUpdateAdjustment.End"/>/<see cref="GanttUpdateAdjustment.Progress"/> substituted in — e.g. snapping a drag to a host's own business-hour grid.</item>
    /// </list>
    /// Leaving this <c>null</c> (the default) accepts every edit
    /// unconditionally, exactly like the pre-promotion "no handler" case.
    /// Synchronous by design — mirrors <see cref="CanDrop"/>'s own
    /// established sync-<c>Func</c> shape (this component's live-drag
    /// validator) so the two "should this happen" hooks share one calling
    /// convention.
    /// </summary>
    [Parameter] public Func<GanttTaskUpdate, GanttUpdateResult>? OnTaskUpdate { get; set; }

    /// <summary>Raised after a task bar's progress changes via the progress handle (design spec Phase 2, T2 — v2-parity <c>OnProgressChange</c>, same contract as v2's <c>Gantt.OnProgressChange</c>). Also folded into <see cref="TasksChanged"/>.</summary>
    [Parameter] public EventCallback<GanttTask> OnProgressChange { get; set; }

    /// <summary>Live scheduling drag-drop validator (design spec Phase 2, T2 — the REUI <c>canDropEvent</c> analog). See <see cref="GanttTimeline.CanDrop"/> for the full contract; passed straight through unchanged.</summary>
    [Parameter] public Func<GanttTask, GanttScheduleDropContext, bool>? CanDrop { get; set; }

