    // time between renders (a live drag), and must resolve against whatever
    // Tasks a render just committed rather than an O(rows) scan repeated on
    // every one of these JSInvokable calls.
    private Dictionary<string, GanttTask> _taskIndex = new();
    private GanttTask? FindTask(string taskId) => _taskIndex.TryGetValue(taskId, out var t) ? t : null;

    /// <summary>
    /// JS -&gt; .NET live row-reorder drop validation (design spec Phase 3, T6
    /// — the REUI <c>canDropEvent</c> analog for tree-row reorder). Mirrors
    /// <see cref="Lumeo.GanttTimeline.ValidateDrop"/>'s exact contract:
    /// permits (<c>true</c>) when <see cref="Readonly"/>, when <see
    /// cref="CanDropRow"/> is unset, or when <paramref name="taskId"/>
    /// doesn't resolve; otherwise resolves the candidate <see
    /// cref="GanttDropContext"/> from THIS component's own <see
    /// cref="Tasks"/> (never trusts JS to compute bucket semantics — see
    /// <see cref="GanttReorderModel"/>'s own remarks) and defers to <see
    /// cref="CanDropRow"/>. <c>[JSInvokable]</c> requires it public — not
    /// meant for direct C# callers outside a test double simulating the JS
    /// side.
    /// </summary>
    [JSInvokable]
    public bool ValidateRowDrop(string taskId, int targetIndex)
    {
        if (Readonly) return true;
        if (CanDropRow is null) return true;

        var task = FindTask(taskId);
        if (task is null) return true;

        var visible = GanttRowModel.FilterValidDurationTasks(Tasks);
        var siblings = GanttReorderModel.SiblingsOf(visible, task);
        if (siblings.Count == 0) return true;
        var clamped = Math.Clamp(targetIndex, 0, siblings.Count - 1);
        var targetSibling = siblings[clamped];
        var targetTaskId = targetSibling.Id == taskId ? null : targetSibling.Id;

        return CanDropRow(task, new GanttDropContext(task.ParentId, clamped, targetTaskId));
    }

    /// <summary>
    /// JS -&gt; .NET row-reorder commit (design spec Phase 3, T6): fired
    /// exactly ONCE, on drop, by gantt-v3.js's <c>registerRowReorderDrag</c>
    /// (which already awaited <see cref="ValidateRowDrop"/> for this SAME
    /// position before ever calling here — mirrors <see
    /// cref="Lumeo.GanttTimeline.CommitDrag"/>'s own "JS validates, commit
    /// trusts it" two-phase split, no redundant re-check here). Resolves the
    /// FULL <see cref="GanttRowReorder"/> payload from THIS component's own
    /// <see cref="Tasks"/> and bubbles it via <see cref="OnRowReorder"/>;
    /// <c>GanttChart.HandleRowReorderAsync</c> applies the equivalent list
    /// reorder AND re-raises the same payload publicly.
    ///
    /// No-ops (server-side guard — design spec Phase 3, T6 "Readonly blocks
    /// both", Phase-2 lesson on a mid-drag Readonly flip surviving
    /// <c>unregisterRowReorderDrag</c> — same reasoning as <see
    /// cref="Lumeo.GanttTimeline.CommitDrag"/>'s own <see cref="Readonly"/>
    /// guard) when <see cref="Readonly"/> or <see cref="AllowRowReorder"/> is
    /// off, when <paramref name="taskId"/> doesn't resolve, or when the
    /// clamped target index equals the task's current index (a genuine
    /// no-op — mirrors <c>CommitDrag</c>'s own <c>movedDays == 0</c> rule).
    /// </summary>
    [JSInvokable]
    public async Task CommitRowReorder(string taskId, int targetIndex)
    {
        if (Readonly || !AllowRowReorder) return;

        var task = FindTask(taskId);
        if (task is null) return;

        var visible = GanttRowModel.FilterValidDurationTasks(Tasks);
        var siblings = GanttReorderModel.SiblingsOf(visible, task);
        var previousIndex = -1;
        for (var i = 0; i < siblings.Count; i++)
        {
            if (siblings[i].Id == taskId) { previousIndex = i; break; }
        }
        if (previousIndex < 0) return;

        var clamped = Math.Clamp(targetIndex, 0, siblings.Count - 1);
        if (clamped == previousIndex) return;

        var reorder = new GanttRowReorder(taskId, task.ParentId, task.ParentId, previousIndex, clamped);
        if (OnRowReorder.HasDelegate) await OnRowReorder.InvokeAsync(reorder);
    }

    // ── Splitter (design spec Phase 3, T5) ──────────────────────────────────
    //
    // Reuses the gantt-v3.js drag-engine conventions (pointer capture, a
    // per-gesture option snapshot taken at pointerdown, pointer-id isolation,
    // reg.activeCleanups) — see gantt-v3.js's own registerSplitterDrag remarks
    // for the full contract. No second drag idiom: the live-drag visual is a
    // DIRECT DOM mutation of this component's own root element (its `width`
    // inline style + the --lumeo-gantt-tree-name-width custom property), never
    // a Blazor round-trip mid-gesture — the ONE JSInvokable call
    // (CommitSplitterWidth) fires exactly once, at gesture end, mirroring
    // GanttTimeline's own CommitDrag/CommitProgress "ghost-only during the
    // drag, one commit at the end" discipline (there is no ghost here because,
    // unlike a task bar, a splitter resize has no invalid/rejectable position
    // to revert away from — see CommitSplitterWidth's own remarks).

    private ElementReference _paneRef;
    private ElementReference _dividerRef;
    private DotNetObjectReference<GanttTree>? _selfRef;
    private bool _splitterRegistered;
    private GanttSplitterOptions _lastSplitterOptions;
    private bool _reorderRegistered;
    // Bug fix (Codex review, P2 #9) — see CommitSplitterWidth's own remarks
    // for why this is a deferred, OnAfterRenderAsync-consumed flag rather
    // than an immediate interop call.
    private bool _pendingSplitterWidthReset;

    // Phase 3, T1's own _taskIndex idiom (GanttTimeline) — rebuilt on EVERY
    // parameter pass (OnParametersSet runs synchronously before any render,
    // including the first), so it always reflects whatever Tasks a render
    // just committed, in lockstep with ReorderPositions/SelectionStates.
    protected override void OnParametersSet()
    {
        var index = new Dictionary<string, GanttTask>(Tasks.Count);
        foreach (var t in Tasks) index[t.Id] = t;
        _taskIndex = index;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        await SyncSplitterRegistrationAsync();
        await SyncRowReorderRegistrationAsync();

        // Bug fix (Codex review, P2 #9): fires exactly once per completed
        // splitter gesture, AFTER this render has genuinely committed — see
        // CommitSplitterWidth's own remarks for why it can't just call this
        // directly. TotalWidth/TreePaneWidth here are therefore the
        // resolved, authoritative values (whatever the parent actually
        // decided, accepted or vetoed), matching exactly what RootStyle's
        // own markup just rendered — so this call is a genuine no-op
        // (re-applies the SAME values the DOM should already show) unless
        // the live drag's own mid-gesture mutation is still sitting there
        // uncorrected.
        if (_pendingSplitterWidthReset)
        {
            _pendingSplitterWidthReset = false;
            await Interop.GanttV3ResetSplitterWidthAsync(_paneRef, TotalWidth, TreePaneWidth);
        }
    }

    // Design spec Phase 3, T6 — registers/unregisters gantt-v3.js's
    // registerRowReorderDrag against THIS pane's own root (_paneRef — the
    // element every row lives inside, mirroring GanttTimeline.SyncDragRegistrationAsync's
    // own "delegate on the container that owns the recycled elements" choice).
    // Readonly is checked FRESH here too (not only at mount), exactly like
    // GanttTimeline.SyncDragRegistrationAsync's own contract — a runtime
    // Readonly (or AllowRowReorder) flip un-registers/re-registers instead of
    // only taking effect at the next mount.
    private async Task SyncRowReorderRegistrationAsync()
    {
        var want = AllowRowReorder && !Readonly;
        if (!want)
        {
            if (_reorderRegistered)
            {
                _reorderRegistered = false;
                try { await Interop.GanttV3UnregisterRowReorderDragAsync(_paneRef); }
                catch (JSDisconnectedException) { }
            }
            return;
        }
        if (_reorderRegistered) return; // no options bag to re-diff — see GanttV3RegisterRowReorderDragAsync's own remarks; register once, idempotent

        _selfRef ??= DotNetObjectReference.Create(this);
        _reorderRegistered = true;
        try
        {
            await Interop.GanttV3RegisterRowReorderDragAsync(_paneRef, _selfRef);
        }
        catch (Exception)
        {
            // Mirrors SyncSplitterRegistrationAsync's own "keep the rest of
            // the pane working when drag interop is unavailable" fix.
            _reorderRegistered = false;
        }
    }

    // Re-registers whenever TreePaneWidth/the min/max clamps actually change
    // (a plain equality-gated skip, mirroring GanttTimeline.SyncDragRegistrationAsync's
    // own GanttInteropOptions-equality gate) — the min/max clamps are compile-time
    // constants so in practice this only re-fires when TreePaneWidth itself
    // moves (a controlled caller pushing a new value, or this component's own
    // prior commit landing back through GanttChart).
    private async Task SyncSplitterRegistrationAsync()
    {
        var options = new GanttSplitterOptions(TreePaneWidth, GanttScale.MinTreePaneWidth, GanttScale.MaxTreePaneWidth);
        if (_splitterRegistered && options == _lastSplitterOptions) return;

        _selfRef ??= DotNetObjectReference.Create(this);
        _splitterRegistered = true;
        _lastSplitterOptions = options;
        try
        {
            await Interop.GanttV3RegisterSplitterDragAsync(_dividerRef, _paneRef, _selfRef, BuildSplitterOptions(options));
        }
        catch (Exception)
        {
            // Mirrors GanttTimeline.SyncDragRegistrationAsync's own "keep
            // pointer clicks when drag interop is unavailable" fix — a failed
            // registration degrades to "the splitter simply can't be dragged"
            // rather than taking the whole render down; a later render retries.
            _splitterRegistered = false;
        }
    }

    private static object BuildSplitterOptions(GanttSplitterOptions options) => new Dictionary<string, object?>
    {
        ["width"] = options.Width,
        ["minWidth"] = options.MinWidth,
        ["maxWidth"] = options.MaxWidth,
    };

    /// <summary>
    /// Called by gantt-v3.js's registerSplitterDrag exactly once per completed
    /// pointer gesture (pointerup with genuine movement — see its own remarks;
    /// a below-threshold/no-movement release never calls this at all, matching
    /// the move/resize drag engine's own "no-op re-render, no commit" rule).
    /// <c>[JSInvokable]</c> requires it public — not meant for direct C# callers
    /// outside a test double simulating the JS side (mirrors GanttTimeline's
    /// own CommitDrag/CommitProgress/CommitCreate).
    ///
    /// Re-clamps defensively (design spec Phase 3, T5 "min/max clamps") even
    /// though the JS side already clamps continuously during the live drag —
    /// this is the untrusted wire boundary, the same reason CommitDrag/
    /// CommitProgress never trust their own string arguments blindly either.
    ///
    /// Bug fix (Codex review, P2 #9): there IS a revert concept here after
    /// all — not an "invalid position" (correct, a splitter has none), but a
    /// CONTROLLED caller vetoing the resulting width entirely (keeping its
    /// own <c>TreePaneWidth</c> unchanged). registerSplitterDrag's own
    /// onPointerMove mutated the real pane element's inline width directly
    /// during the gesture; if Blazor's next render computes the SAME style
    /// string it rendered before (a veto), its diff never re-touches the
    /// DOM, leaving that JS-mutated width stuck in place. Arms
    /// <see cref="_pendingSplitterWidthReset"/> rather than force-syncing the
    /// DOM right here — matching v2 Gantt's own established "always re-push,
    /// don't rely on Blazor's diff" controlled-rollback pattern
    /// (<c>GanttControlledRollbackTests</c>), but deferred to the NEXT
    /// <see cref="OnAfterRenderAsync"/> (see that flag's own remarks for
    /// why: this method's own <c>OnResize.InvokeAsync</c> completing does
    /// not guarantee the parent's resulting decision has already propagated
    /// back down through a fresh render of THIS component yet).
    /// </summary>
    [JSInvokable]
    public async Task CommitSplitterWidth(double width)
    {
        var clamped = Math.Clamp(width, GanttScale.MinTreePaneWidth, GanttScale.MaxTreePaneWidth);
        if (OnResize.HasDelegate) await OnResize.InvokeAsync(clamped);
        // Deferred to the NEXT OnAfterRenderAsync rather than force-synced
        // right here: OnResize.InvokeAsync's own completion does not
        // guarantee Blazor has ALREADY propagated the parent's resulting
        // TreePaneWidth decision back down through a fresh render of THIS
        // component — reading TotalWidth/TreePaneWidth immediately here
        // could still observe the PRE-round-trip values. OnAfterRenderAsync
        // only ever runs after a genuine render has committed, guaranteeing
        // whatever it reads is the resolved, authoritative post-decision
        // state (accepted OR vetoed).
        _pendingSplitterWidthReset = true;
    }

    // Keyboard resize (WAI-ARIA separator pattern parity with Lumeo's own
    // SplitterDivider/ResizableHandle): a single discrete commit per keypress,
    // through the SAME OnResize callback the pointer-drag commit uses — not a
    // second idiom, just a second TRIGGER for the one commit path. RTL swaps
    // Left/Right so the key pointing toward this pane's own visual "start"
    // always shrinks it, mirroring SplitterDivider.OnKeyDown's identical rule.
    private Task OnSplitterKeyDown(KeyboardEventArgs e)
    {
        const double step = 16.0;
        const double toBound = 1_000_000.0; // clamped to the actual bound by Math.Clamp below
        var isRtl = EffectiveDirection == LayoutDirection.Rtl;

        var delta = e.Key switch
        {
            "ArrowLeft" => isRtl ? step : -step,
            "ArrowRight" => isRtl ? -step : step,
            "Home" => isRtl ? toBound : -toBound,
            "End" => isRtl ? -toBound : toBound,
            _ => 0.0,
        };
        if (delta == 0.0) return Task.CompletedTask;

        var next = Math.Clamp(TreePaneWidth + delta, GanttScale.MinTreePaneWidth, GanttScale.MaxTreePaneWidth);
        if (Math.Abs(next - TreePaneWidth) < 0.5) return Task.CompletedTask;
        return OnResize.HasDelegate ? OnResize.InvokeAsync(next) : Task.CompletedTask;
    }

    public async ValueTask DisposeAsync()
    {
        if (_splitterRegistered)
        {
            try { await Interop.GanttV3UnregisterSplitterDragAsync(_dividerRef); }
            catch (JSDisconnectedException) { }
        }
        if (_reorderRegistered)
        {
            try { await Interop.GanttV3UnregisterRowReorderDragAsync(_paneRef); }
            catch (JSDisconnectedException) { }
        }
        _selfRef?.Dispose();
    }
}

namespace Lumeo.GanttV3;

/// <summary>
/// Discriminates WHY a <see cref="GanttTaskUpdate"/> fired (design spec "Public
/// API" &gt; Additive &gt; "Unified commit gate with source discriminator" — the
/// REUI <c>onEventUpdate</c> "source" analog). Defined in full now (Phase 2, T1)
/// even though <see cref="Progress"/>/<see cref="Create"/> are not yet raised by
/// any code path — T2 (progress drag) and T3 (drag-create) are the tasks that
/// fire them — so promoting this enum later never requires a breaking rename or
/// a second, incompatible discriminator type.
///
/// <c>public</c> (not <c>internal</c>): this crosses <c>GanttTimeline</c>/
/// <c>GanttChart</c>'s public <c>OnTaskUpdate</c> gate parameter (both
/// unavoidably public components — see <see cref="GanttRowKind"/>'s remarks
/// for the CS0053/Razor-compiler background), so a less-accessible type here
/// would not compile. Promoted (Phase 4): recorded in PublicAPI.Shipped.txt,
/// <c>[EditorBrowsable(Never)]</c> lifted.
/// </summary>
public enum GanttTaskUpdateSource
{
    /// <summary>The task's Start/End shifted together (drag-move) — duration unchanged.</summary>
    Move,
    /// <summary>The task's Start moved via the left resize handle; End unchanged (REUI parity — v2 has no left-edge resize).</summary>
    ResizeStart,
    /// <summary>The task's End moved via the right resize handle; Start unchanged (v2 parity — v2's only resize direction).</summary>
    ResizeEnd,
    /// <summary>The task's Progress changed via the progress handle (T2 — not yet raised).</summary>
    Progress,
    /// <summary>A new task was created via drag-create on an empty track (T3 — not yet raised).</summary>
    Create,
    /// <summary>
    /// The task's Start/End (or just End, for a keyboard resize) changed via
    /// keyboard nudging on a focused bar — Shift+Arrow to move, Shift+Up/Down
    /// to resize the End edge (see <see cref="Lumeo.GanttTimeline"/>'s own
    /// keyboard-navigation remarks). Mirrors ReUI's own keyboard-drag
    /// behavior, which tags every such edit with a single flat "keyboard"
    /// source regardless of whether it was a move or a resize — this enum
    /// does the same rather than adding separate KeyboardMove/
    /// KeyboardResizeEnd members, so a consumer's <c>OnTaskUpdate</c> gate can
    /// cheaply special-case "this came from the keyboard, not a mouse drag"
    /// with one check.
    /// </summary>
    Keyboard,
}

/// <summary>
/// Unified commit-gate payload (design spec "Public API" &gt; Additive &gt;
/// "Unified commit gate with source discriminator (onEventUpdate analog) ...
/// OnTaskUpdate(GanttTaskUpdate{Task, Source})"). Raised by <see
/// cref="Lumeo.GanttTimeline"/> and evaluated by <see cref="Lumeo.GanttChart"/>'s
/// <c>OnTaskUpdate</c> gate BEFORE it commits — see <see cref="GanttUpdateResult"/>
/// for the reject/accept/adjust verdict a consumer's <c>OnTaskUpdate</c> returns.
///
/// <c>public</c> — see <see cref="GanttTaskUpdateSource"/>'s remarks for why
/// (crosses the same public delegate-parameter boundary). Promoted (Phase 4):
/// recorded in PublicAPI.Shipped.txt, <c>[EditorBrowsable(Never)]</c> lifted.
/// </summary>
/// <param name="Task">
/// The task/milestone as it WOULD be committed if <c>OnTaskUpdate</c> accepts
/// (Phase 4 — before promotion this was already-committed; see
/// <see cref="GanttUpdateResult"/>'s own remarks for the pre-commit-gate change).
/// </param>
/// <param name="Source">Which gesture produced this update.</param>
public sealed record GanttTaskUpdate(GanttTask Task, GanttTaskUpdateSource Source);

/// <summary>
/// One arrow-key press on a focused <see cref="Lumeo.GanttBar"/> (wheel-zoom's
/// keyboard-navigation sibling feature). Raised by <see cref="Lumeo.GanttBar"/>'s
/// own <c>OnKeyNavigation</c> and consumed by <see cref="Lumeo.GanttTimeline"/>,
/// which decides what it means: with no modifier, roving focus moves to the
/// previous/next visible row's bar; with <see cref="ShiftKey"/> held, the
/// FOCUSED task's own schedule is nudged instead (Left/Right moves the whole
/// task by a day, Up/Down grows/shrinks its End edge by a day) and routed
/// through the same <c>OnTaskUpdate</c> commit gate a mouse drag uses, tagged
/// <see cref="GanttTaskUpdateSource.Keyboard"/>.
///
/// <c>public</c> — crosses <see cref="Lumeo.GanttBar"/>'s public
/// <c>EventCallback&lt;GanttBarKeyNavigation&gt; OnKeyNavigation</c> parameter
/// (same CS0053 public-parameter-can't-expose-a-less-accessible-type
/// constraint <see cref="GanttTaskUpdateSource"/>'s remarks explain).
/// </summary>
/// <param name="Task">The bar that had focus when the key was pressed.</param>
/// <param name="Key">The raw <c>KeyboardEvent.key</c> value — one of "ArrowUp"/"ArrowDown"/"ArrowLeft"/"ArrowRight".</param>
/// <param name="ShiftKey">Whether Shift was held — the focus-move/schedule-edit discriminator (see the class remarks).</param>
public sealed record GanttBarKeyNavigation(GanttTask Task, string Key, bool ShiftKey);

/// <summary>
/// A candidate override for a commit's Start/End/Progress, offered by a
/// <c>GanttChart.OnTaskUpdate</c> gate when it accepts a
/// <see cref="GanttTaskUpdate"/> but wants to snap it to different values than
/// the raw proposal (e.g. round a drag to the nearest business-hour boundary
/// instead of merely refusing an out-of-hours drop). Mirrors ReUI's
/// <c>onEventUpdate</c> return shape (<c>{ start?, end?, allDay? }</c>) — see
/// <see cref="GanttUpdateResult"/>. <c>AllDay</c> has no Gantt-task analog (a
/// <see cref="GanttTask"/> is always a date range, never an all-day flag), so
/// this substitutes <see cref="Progress"/> instead: the ONE other field every
/// <see cref="GanttChart.OnTaskUpdate"/> commit can carry (progress-handle
/// drags flow through the exact same gate as move/resize/create), which ReUI's
/// own Gantt has no equivalent gesture for at all. Any member left
/// <c>null</c> keeps the corresponding proposed value from <see
/// cref="GanttTaskUpdate.Task"/> unchanged.
/// </summary>
/// <param name="Start">Overrides the committed task's Start when set.</param>
/// <param name="End">Overrides the committed task's End when set.</param>
/// <param name="Progress">Overrides the committed task's Progress (0-100) when set.</param>
public sealed record GanttUpdateAdjustment(DateTime? Start = null, DateTime? End = null, int? Progress = null);

/// <summary>
/// The three-way verdict a <c>GanttChart.OnTaskUpdate</c> gate returns for a
/// proposed <see cref="GanttTaskUpdate"/>: reject it outright (nothing commits,
/// <see cref="Lumeo.GanttChart.TasksChanged"/>/<c>OnDateChange</c>/etc. never
/// fire), accept it exactly as proposed, or accept it WITH a <see
/// cref="GanttUpdateAdjustment"/> that snaps the eventually-committed
/// Start/End/Progress to different values than what was proposed. This is the
/// ONE breaking change in the Phase-4 promotion (design spec Wave E1 / the
/// ReUI-parity audit's E1): <c>OnTaskUpdate</c> was a post-commit
/// <c>EventCallback&lt;GanttTaskUpdate&gt;</c> notification through Phase 3 —
/// the edit had already landed in <c>GanttState</c> by the time it fired, so it
/// could not reject or adjust anything. Converting it to a real gate BEFORE
/// promotion (rather than after, once a consumer could depend on the old
/// void/notification shape) is what keeps this free — see the promotion PR
/// body for the full reasoning.
///
/// Mirrors <c>Lumeo.SchedulerDropResult</c> (<c>src/Lumeo.Scheduler/UI/
/// SchedulerViews/SchedulerInteractionTypes.cs</c>) by design, for the same
/// "one accept/reject/adjust shape across the library" reasoning that type's
/// own remarks give — deliberately not a NEW pattern invented just for Gantt.
///
/// An implicit <c>bool</c> conversion keeps the common "just let it through"
/// case exactly as simple as returning a raw <c>bool</c> — e.g.
/// <c>OnTaskUpdate="update => true"</c> compiles directly against the
/// <c>Func&lt;GanttTaskUpdate, GanttUpdateResult&gt;</c> parameter type, and
/// leaving <c>OnTaskUpdate</c> unset (<c>null</c>, the default) keeps every
/// edit accepted unconditionally — byte-identical to Phase 1-3's own
/// "no OnTaskUpdate handler wired up" behavior.
/// </summary>
public readonly struct GanttUpdateResult : IEquatable<GanttUpdateResult>
{
    /// <summary>Whether the update is permitted at all (with or without an <see cref="Adjustment"/>).</summary>
    public bool Accepted { get; }

    /// <summary>
    /// When set, the Start/End/Progress a consumer wants committed instead of
    /// the raw <see cref="GanttTaskUpdate.Task"/> proposal. Always <c>null</c>
    /// when <see cref="Accepted"/> is <c>false</c> (a rejected update has
    /// nothing to adjust).
    /// </summary>
    public GanttUpdateAdjustment? Adjustment { get; }

    private GanttUpdateResult(bool accepted, GanttUpdateAdjustment? adjustment)
    {
        Accepted = accepted;
        Adjustment = accepted ? adjustment : null;
    }

    /// <summary>Rejects the update outright — nothing commits.</summary>
    public static readonly GanttUpdateResult Reject = new(false, null);

    /// <summary>Accepts the update exactly as proposed — no adjustment.</summary>
    public static readonly GanttUpdateResult Accept = new(true, null);

    /// <summary>Accepts the update, but commits <paramref name="adjustment"/>'s values instead of the raw proposal.</summary>
    public static GanttUpdateResult AcceptWith(GanttUpdateAdjustment adjustment) => new(true, adjustment);

    /// <summary>Keeps <c>OnTaskUpdate="update => true"</c>/<c>false</c> lambdas source-compatible with the delegate type.</summary>
    public static implicit operator GanttUpdateResult(bool accepted) => accepted ? Accept : Reject;

    public bool Equals(GanttUpdateResult other) => Accepted == other.Accepted && Equals(Adjustment, other.Adjustment);
    public override bool Equals(object? obj) => obj is GanttUpdateResult other && Equals(other);
    public override int GetHashCode() => HashCode.Combine(Accepted, Adjustment);
    public static bool operator ==(GanttUpdateResult left, GanttUpdateResult right) => left.Equals(right);
    public static bool operator !=(GanttUpdateResult left, GanttUpdateResult right) => !left.Equals(right);
}

/// <summary>
/// Payload for a completed tree-pane row reorder (design spec "Public API" &gt;
/// Additive &gt; <c>AllowRowReorder</c> + <c>EventCallback&lt;GanttRowReorder&gt;</c>).
/// Raised once, after drop, with the task's old and new position.
///
/// <c>public</c> (design spec Phase 3, T6): promoted the moment <c>GanttChart</c>/
/// <c>GanttTree</c> actually wire up drag-drop reorder. Recorded in
/// PublicAPI.Shipped.txt as of the Phase-4 promotion.
///
/// <b>Within-parent/within-bucket only</b> (T6 decision #3 — REUI semantics; a
/// cross-parent move is a <see cref="GanttTask.ParentId"/> EDIT, out of this
/// feature's scope by design, never offered through the drag UI at all):
/// <see cref="PreviousParentId"/> and <see cref="NewParentId"/> are therefore
/// ALWAYS equal for any reorder this library itself ever raises — both fields
/// are kept (rather than a single <c>ParentId</c>) only so a future cross-parent
/// feature could reuse this exact record without a breaking shape change.
///
/// <b>Flat <see cref="GanttTask.GroupLabel"/> grouping</b> (no <see
/// cref="GanttTask.ParentId"/> in play — <see cref="GanttRowModel.UsesHierarchy"/>
/// false for the task set): <see cref="PreviousParentId"/>/<see cref="NewParentId"/>
/// are <c>null</c> throughout (a flat task's <c>ParentId</c> genuinely never
/// changes), and <see cref="PreviousIndex"/>/<see cref="NewIndex"/> are the
/// task's index among its OWN <see cref="GanttTask.GroupLabel"/>-sharing siblings
/// (the "bucket" — see <see cref="Lumeo.GanttV3.GanttReorderModel"/>'s own
/// remarks), NOT a global root-level index — reordering across two DIFFERENT
/// groups is exactly as out-of-scope as a cross-parent move in hierarchy mode.
/// </summary>
/// <param name="TaskId">Id of the task/row that was moved.</param>
/// <param name="PreviousParentId">The task's <see cref="GanttTask.ParentId"/> before the move (null = root, or always null in flat-group mode — see the class remarks).</param>
/// <param name="NewParentId">The task's <see cref="GanttTask.ParentId"/> after the move — always equal to <see cref="PreviousParentId"/> (within-bucket only — see the class remarks).</param>
/// <param name="PreviousIndex">Index within the task's reorder bucket (see the class remarks) before the move.</param>
/// <param name="NewIndex">Index within the task's reorder bucket (see the class remarks) after the move.</param>
public sealed record GanttRowReorder(
    string TaskId,
    string? PreviousParentId,
    string? NewParentId,
    int PreviousIndex,
    int NewIndex);

/// <summary>
/// Live drag-drop validation context for TREE-ROW reorder (design spec "Public
/// API" &gt; Additive &gt; <c>AllowRowReorder</c> — the REUI <c>canDropEvent</c>
/// analog applied to row reorder rather than schedule dragging; see <see
/// cref="GanttScheduleDropContext"/>'s own remarks for why THAT is a separate,
/// differently-shaped type). Passed alongside the dragged <see cref="GanttTask"/>
/// to a consumer-supplied <c>CanDropRow</c> predicate evaluated continuously
/// while a row drag is in flight (<c>GanttTree.ValidateRowDrop</c>), so the drop
/// target can be rejected (e.g. "no dropping a parent onto its own descendant")
/// before the user releases the pointer, then re-checked once more at commit
/// time (<c>GanttTree.CommitRowReorder</c>) — same two-phase discipline
/// <c>GanttTimeline.ValidateDrop</c>/<c>CommitDrag</c> already established for
/// schedule dragging.
///
/// <c>public</c> (design spec Phase 3, T6): promoted the moment <c>GanttChart</c>/
/// <c>GanttTree</c> expose a <c>CanDropRow</c> parameter wired to it. Recorded
/// in PublicAPI.Shipped.txt as of the Phase-4 promotion.
///
/// <b>Flat-group mode</b>: <see cref="TargetParentId"/> is always <c>null</c>
/// (a flat task's <see cref="GanttTask.ParentId"/> never changes — see <see
/// cref="GanttRowReorder"/>'s own remarks) even though the candidate drop
/// position is really scoped to one <see cref="GanttTask.GroupLabel"/> bucket;
/// a consumer that needs the group can resolve it from <see cref="TargetTaskId"/>
/// (or from the dragged task's own <c>GroupLabel</c>, unchanged by a
/// within-bucket move).
/// </summary>
/// <param name="TargetParentId">The dragged task's <see cref="GanttTask.ParentId"/> (null = root, or always null in flat-group mode — see the class remarks). Never a DIFFERENT parent than the dragged task's own — reorder is within-bucket only.</param>
/// <param name="TargetIndex">The candidate index within the dragged task's own reorder bucket at the current drop position.</param>
/// <param name="TargetTaskId">Id of the sibling row currently nearest the pointer, if any (null when hovering past the last sibling).</param>
public sealed record GanttDropContext(
    string? TargetParentId,
    int TargetIndex,
    string? TargetTaskId);

/// <summary>
/// Live SCHEDULING drag-drop validation context (design spec Phase 2, T2 —
/// <c>Func&lt;GanttTask, GanttDropContext, bool&gt;? CanDrop</c>, the REUI
/// <c>canDropEvent</c> analog applied to move/resize dragging rather than tree-pane
/// reordering). Evaluated by a consumer-supplied predicate while a move/resize drag
/// is in flight (<see cref="Lumeo.GanttTimeline.ValidateDrop"/>), so the drop position
/// can be rejected (ghost painted invalid, drop reverts) before the pointer is released.
///
/// <b>Naming note:</b> the plan's T2 task text describes this parameter as
/// "<c>GanttDropContext</c> from T1 types: proposed Start/End, Source" — but the
/// <see cref="GanttDropContext"/> record ALREADY defined above (Phase 2 plan's own
/// "Additive" list) is a DIFFERENT shape, purpose-built for Phase 3's tree-pane ROW
/// reorder (<c>TargetParentId</c>/<c>TargetIndex</c>/<c>TargetTaskId</c> — "where in
/// the hierarchy", not "what dates"). Reusing that name/shape here would either break
/// Phase 3's future row-reorder validation or require inventing a second, differently
/// named type for THAT purpose instead — so this SCHEDULING validation context gets
/// its own name instead. Flagged for the reviewer: this is a deliberate deviation from
/// the plan's literal wording, not an oversight.
///
/// <c>public</c> (not <c>internal</c>): crosses <see cref="Lumeo.GanttChart"/>/
/// <see cref="Lumeo.GanttTimeline"/>'s public <c>Func&lt;GanttTask,
/// GanttScheduleDropContext, bool&gt;? CanDrop</c> parameters (same CS0053
/// public-parameter-can't-expose-a-less-accessible-type constraint as
/// <see cref="GanttTaskUpdateSource"/>'s remarks explain). Recorded in
/// PublicAPI.Shipped.txt as of the Phase-4 promotion.
/// </summary>
/// <param name="ProposedStart">The task's <see cref="GanttTask.Start"/> if this drop were committed.</param>
/// <param name="ProposedEnd">The task's <see cref="GanttTask.End"/> if this drop were committed.</param>
/// <param name="Source">
/// Which gesture produced this candidate position — always <see cref="GanttTaskUpdateSource.Move"/>,
/// <see cref="GanttTaskUpdateSource.ResizeStart"/>, or <see cref="GanttTaskUpdateSource.ResizeEnd"/>;
/// never <see cref="GanttTaskUpdateSource.Progress"/> (progress dragging is not validated —
/// <c>CanDrop</c> is a scheduling/REUI concept, not a progress-percentage one) or
/// <see cref="GanttTaskUpdateSource.Create"/> (T3's own concern).
/// </param>
public sealed record GanttScheduleDropContext(
    DateTime ProposedStart,
    DateTime ProposedEnd,
    GanttTaskUpdateSource Source);

/// <summary>
/// The drag-relevant fields <see cref="Lumeo.GanttTimeline"/> pushes to the JS
/// drag engine (design spec Phase 3, T1 — "replace the growing
/// <c>HashCode.Combine</c> options-hash with an options record"). Replaces a
/// plain <c>int</c> hash of the same fields: a record's synthesized structural
/// equality (<c>==</c>/<c>!=</c>, <c>Equals</c>) directly answers "did anything
/// drag-relevant actually change" with no collision risk and no fixed argument
/// ceiling to run into as more fields join it (<c>HashCode.Combine</c> only
/// overloads up to 8 arguments; this was already at 5 and the Phase-3
/// watch-list — reorder/selection/splitter — only adds more candidates).
///
/// Compared once per render in <see cref="Lumeo.GanttTimeline.SyncDragRegistrationAsync"/>
/// against the previously-registered value: an unchanged value skips the
/// <c>GanttV3RegisterDragAsync</c> interop round-trip entirely, the same
/// short-circuit the old hash comparison provided. This is a PERFORMANCE gate
/// only, not a drag-safety one — gantt-v3.js's own <c>registerDrag</c> already
/// snapshots <c>reg.options</c> into a local at the moment a gesture begins
/// (see its own "Snapshot drag options at pointerdown" remarks), so even a
/// registration call that DOES land mid-drag (a genuine options change while a
/// gesture is already in flight) only updates the STORED config for the NEXT
/// gesture — the currently-running one keeps reading its own local snapshot
/// and is structurally unreachable by the swap. Record-equality re-registration
/// therefore changes nothing about drag safety; it keeps the interop call
/// count low exactly as the hash did, just without a hash's collision risk and
/// without capping how many fields can ever describe "the options".
/// </summary>
/// <param name="ColumnWidth"><see cref="Lumeo.GanttTimeline.EffectiveColumnWidth"/> at push time.</param>
/// <param name="PixelsPerDay"><see cref="Lumeo.GanttTimeline.PixelsPerDay"/> at push time (move/resize snap math).</param>
/// <param name="HasCanDrop">Whether <see cref="Lumeo.GanttTimeline.CanDrop"/> is set (gates whether JS ever calls <c>ValidateDrop</c> at all).</param>
/// <param name="AllowCreate"><see cref="Lumeo.GanttTimeline.AllowCreate"/> at push time.</param>
/// <param name="Origin">The row-canvas-space date origin (drag-create's only anchor — see <c>BuildDragOptions</c>'s remarks).</param>
/// <param name="NowDate">
/// <see cref="Lumeo.GanttTimeline.EffectiveNow"/>'s DATE part at push time, so the drag
/// engine's own <c>data-past</c> refresh on the ghost uses the SAME clock the bars do
/// (Codex review of the styling-hooks PR, P2). The JS side previously read
/// <c>new Date()</c>, which silently ignored a consumer-supplied
/// <see cref="Lumeo.GanttTimeline.Now"/> — a historical or simulated timeline then had
/// ghosts contradicting the very bars they were cloned from.
/// <para>
/// Only the date part travels, deliberately: it is all the whole-day past-ness rule
/// needs, and it means this field changes at most once per calendar day rather than on
/// every clock resolve — so adding it to this equality-compared snapshot does not turn
/// the registration short-circuit into a re-registration treadmill.
/// </para>
/// </param>
internal readonly record struct GanttInteropOptions(
    int ColumnWidth,
    double PixelsPerDay,
    bool HasCanDrop,
    bool AllowCreate,
    DateTime Origin,
    DateTime NowDate);

/// <summary>
/// A duration-weighted rollup summary for one hierarchy-parent or flat-group
/// row (design spec Phase 3, T3 — "Duration-weighted progress rollup per
/// parent/group row (<c>GanttRollup</c> record: Start, End, WeightedProgress)").
/// Produced by <see cref="GanttRollupModel"/> (the default math) or by a
/// consumer's own <c>RollupMath</c> override — see
/// <see cref="Lumeo.GanttTimeline.RollupMath"/>'s remarks for the exact
/// per-parent-row invocation contract (direct children only; a nested
/// parent's OWN already-computed rollup stands in for its raw Start/End/
/// Progress, which is what makes a multi-level hierarchy roll up
/// transitively without <c>RollupMath</c> itself needing to know anything
/// about recursion).
///
/// A <c>readonly record struct</c> (not a class) — mirrors
/// <see cref="GanttVisibleRow"/>'s own choice: one of these is computed per
/// parent/group row, every render, so avoiding a per-row heap allocation
/// matters the same way it did there (see that type's remarks).
///
/// <c>public</c> — crosses <see cref="Lumeo.GanttTimeline"/>/<see cref="Lumeo.GanttChart"/>'s
/// public <c>RollupMath</c>/<c>SummaryTemplate</c> parameters (same CS0053
/// public-parameter-can't-expose-a-less-accessible-type constraint as
/// <see cref="GanttTaskUpdateSource"/>'s remarks explain). Recorded in
/// PublicAPI.Shipped.txt as of the Phase-4 promotion.
/// </summary>
/// <param name="Start">The earliest effective Start across the row's direct children (a nested parent contributes its OWN rolled-up Start, not its raw one).</param>
/// <param name="End">The latest effective End across the row's direct children, same substitution rule as <paramref name="Start"/>.</param>
/// <param name="WeightedProgress">
/// Duration-weighted mean progress across the row's direct children, 0-100
/// (fractional — the renderer rounds for display). See
/// <see cref="GanttRollupModel"/>'s remarks for the exact weighting formula
/// and how a zero-duration milestone child is handled without dividing by
/// zero or dropping out of the average.
/// </param>
public readonly record struct GanttRollup(DateTime Start, DateTime End, double WeightedProgress);

/// <summary>
/// One extra tree-pane column rendered after the pinned name column (design
/// spec Phase 3, T5 — REUI "Multi-column task tree"). The name column itself
/// (indent + expander chrome + label/<c>RowTemplate</c>) is never one of
/// these — it is not resizable-per-column, always first, and always pinned;
/// see <c>Lumeo.GanttTree</c>'s own remarks for why the two are kept
/// structurally separate rather than modeling the name column as "just
/// another <see cref="GanttTreeColumn"/>".
///
/// <c>public</c> — crosses <c>Lumeo.GanttChart</c>/<c>Lumeo.GanttTree</c>'s public
/// <c>IReadOnlyList&lt;GanttTreeColumn&gt;? TreeColumns</c> parameters (same
/// CS0053 public-parameter-can't-expose-a-less-accessible-type constraint as
/// <see cref="GanttTaskUpdateSource"/>'s remarks explain). Recorded in
/// PublicAPI.Shipped.txt as of the Phase-4 promotion.
/// </summary>
/// <param name="Title">Header-row label for this column (rendered as plain text — no v2/REUI localization contract for a CONSUMER-supplied column title, same as <c>GanttTask.Name</c> itself).</param>
/// <param name="Width">Fixed pixel width. Unlike the pinned name column (resized by the splitter — see <c>TreePaneWidth</c>), extra columns are NOT individually resizable in T5's scope; a consumer wanting a wider column sets a bigger <see cref="Width"/> directly.</param>
/// <param name="CellTemplate">
/// Per-row cell content for a TASK row (<c>GanttVisibleRow.Task</c> non-null).
/// Never invoked for a <c>GanttRowKind.GroupHeader</c> row (no
/// <see cref="GanttTask"/> to feed it) — that row's cell for this column
/// renders empty, preserving column alignment without a synthetic/null task.
/// </param>
public sealed record GanttTreeColumn(string Title, int Width, Microsoft.AspNetCore.Components.RenderFragment<GanttTask> CellTemplate);

/// <summary>
/// The splitter-relevant fields <see cref="Lumeo.GanttTree"/> pushes to the JS
/// splitter-drag engine (design spec Phase 3, T5) — the SAME "record instead
/// of a growing options bag" idiom <see cref="GanttInteropOptions"/> already
/// established for the move/resize/progress drag engine (see its own
/// remarks): a record's structural equality lets <c>GanttTree</c> skip the
/// <c>GanttV3RegisterSplitterDragAsync</c> interop round-trip whenever nothing
/// drag-relevant actually changed, with no second drag idiom introduced.
/// </summary>
/// <param name="Width">The pinned name column's CURRENT effective width in pixels — the live-drag start point the JS side snapshots at pointerdown (mirrors <c>GanttInteropOptions</c>'s own "JS never re-derives, C# is the source of truth" discipline).</param>
/// <param name="MinWidth"><see cref="Lumeo.GanttV3.GanttScale.MinTreePaneWidth"/> — the live JS-side floor during drag.</param>
/// <param name="MaxWidth"><see cref="Lumeo.GanttV3.GanttScale.MaxTreePaneWidth"/> — the live JS-side ceiling during drag.</param>
internal readonly record struct GanttSplitterOptions(double Width, double MinWidth, double MaxWidth);

using Lumeo.Services;

namespace Lumeo.GanttV3;

/// <summary>
/// A value snapshot of every input that can move the GanttV3 viewport
/// (design spec Phase 2; Codex round 14 consolidation). Captured once per
/// reconcile pass in <c>GanttChart</c> and diffed against the previous pass's
/// snapshot by <see cref="GanttViewportReconciler.Decide"/> — the single
/// replacement for the per-parameter tracking fields
/// (<c>_lastSeenDirection</c>/<c>_lastSeenEffectiveShowTreePane</c>/
/// <c>_lastSeenColumnWidth</c>/<c>_lastPushedViewMode</c>) that rounds 11-13
/// accreted one at a time.
/// </summary>
/// <param name="TasksVersion">A monotonic counter <c>GanttChart</c> bumps whenever the
/// effective task set actually changes (structural inequality via
/// <c>GanttState</c>) — a diff on it is the exact <c>tasksChanged</c> signal,
/// captured as a plain value so the whole decision stays a pure snapshot diff.</param>
/// <param name="RenderableEmpty">Whether the FILTERED/renderable row set is empty —
/// i.e. after <see cref="GanttRowModel.FilterValidDurationTasks"/>, the same set
/// that actually reaches the panes (Codex round 14, finding #2). A raw task count
/// would misclassify a list of only invalid-duration tasks as "populated".</param>
/// <param name="ViewMode">The mode the chart is reconciling TO — the incoming
/// parameter for a controlled binding, or the committed <c>GanttState.ViewMode</c>
/// for an uncontrolled one whose parameter re-render must not revert a toolbar zoom.</param>
/// <param name="ColumnWidth">The effective pixel-per-column width for
/// <see cref="ViewMode"/> — a caller's override when set, else the mode's own
/// default. Computed against THIS snapshot's own <see cref="ViewMode"/>, so a mode
/// switch that changes the default width records the width consistent with the mode
/// it belongs to (Codex round 14, finding #1 — the old code recorded the OUTGOING
/// mode's default and then saw a spurious change on the next echo).</param>
/// <param name="ShowTreePane">The resolved <c>EffectiveShowTreePane</c> — a tree-pane
/// visibility change shifts the timeline's leading offset and so needs a recenter.</param>
/// <param name="Direction">The resolved ambient <see cref="LayoutDirection"/> — a flip
/// re-interprets the physical scroll position (RTL normalization), so it triggers a
/// center-preserving recenter even when the leading offset itself is unchanged.</param>
/// <param name="TreePaneWidth">
/// The combined physical width (pixels) of the tree pane's pinned name column PLUS
/// any <c>GanttTreeColumn</c>s (design spec Phase 3, T5 — <c>GanttChart.EffectiveTreePaneTotalWidth</c>).
/// Feeds <see cref="LeadingOffset"/> the SAME way <see cref="ShowTreePane"/>/
/// <see cref="Direction"/> already do — a splitter drag changes how many pixels of
/// tree pane precede the timeline's own origin inside the shared scroll container,
/// so a LATER reconcile's live-scroll-center capture must decode against the width
/// that was actually on screen when THIS snapshot was committed, not a stale one.
/// </param>
internal readonly record struct GanttViewportSnapshot(
    int TasksVersion,
    bool RenderableEmpty,
    GanttViewMode ViewMode,
    int ColumnWidth,
    bool ShowTreePane,
    LayoutDirection Direction,
    double TreePaneWidth)
{
    /// <summary>
    /// Pixels of the shared scroll pane preceding the timeline's origin under THIS
    /// snapshot's geometry — a sibling tree pane's width in LTR, else 0. The exact
    /// value a live-scroll-center reading captured under this snapshot must be
    /// decoded against (see <c>GanttChart.ResolveCurrentCenterDateAsync</c>).
    /// </summary>
    public double LeadingOffset => GanttViewportGeometry.LeadingOffset(ShowTreePane, Direction, TreePaneWidth);
}

/// <summary>Where the reconciled <c>VisibleRange</c> comes from for a pass.</summary>
internal enum GanttRangeSource
{
    /// <summary>Leave <c>VisibleRange</c> untouched — only the scroll target (if any) moves.</summary>
    Keep,

    /// <summary>Rebuild from the (new) task set's own min/max via <c>ComputeInitialRange</c>.</summary>
    TaskDerived,

    /// <summary>Rebuild as a padded window self-centered on the captured live center (a genuine mode switch reshapes columns).</summary>
    SelfCenteredOnCapture,
}

/// <summary>
/// The result of one <c>GanttChart.ReconcileAsync</c> call (Codex round 18-f2). A
/// caller must distinguish these three, not just "did it commit": a
/// <see cref="Superseded"/> pass never applied its pending parameter inputs, so
/// the SUPERSEDING action (a navigation, a theme flip) must re-apply them; a
/// <see cref="NoOp"/> pass had nothing to apply (nothing changed since the last
/// commit) and needs no follow-up.
/// </summary>
internal enum GanttReconcileOutcome
{
    /// <summary>The pass captured (if needed), committed tasks/mode/range, and emitted its scroll intent.</summary>
    Committed,

    /// <summary>Nothing in the snapshot diff changed — the pass abandoned before claiming a generation, committing nothing.</summary>
    NoOp,

    /// <summary>A newer generation was claimed while this pass's capture was in flight — it abandoned its entire commit, so its pending inputs are still un-applied.</summary>
    Superseded,
}

/// <summary>
/// Which trigger authored the view-mode intent that currently owns
/// <c>GanttState.ViewMode</c> (Codex PR-382 review round 3 consolidation — see
/// <see cref="GanttViewModeIntent"/>).
/// </summary>
/// <remarks>
/// Deliberately has no <c>Navigation</c> member: a Previous/Next/Today click (or
/// a <c>ThemeService</c> direction flip) never DECIDES a view mode. It supersedes
/// whichever reconcile is carrying the current intent and REPLAYS that same
/// intent — it is a re-executor, never an author. Making that fact structural is
/// half the point of this type: the replay path has no branch that could invent a
/// mode of its own, or fall back to reading a parameter that a controlled binding
/// has not echoed yet.
/// </remarks>
internal enum GanttViewModeSource
{
    /// <summary>The initial <c>ViewMode</c> parameter value, adopted by <c>OnInitialized</c>.</summary>
    Mount,

    /// <summary>A genuine <c>ViewMode</c> parameter change pushed by the parent on a parameter pass.</summary>
    Parameter,

    /// <summary>A zoom pick from <c>GanttNav</c>'s toolbar.</summary>
    Toolbar,

    /// <summary>
    /// A programmatic <c>GanttState.SetViewMode</c> call (design spec Phase 3, T4 —
    /// the REUI apiRef <c>setViewMode</c> analog), claimed via
    /// <c>GanttChart.ApplyViewModeIntentAsync</c> — the SAME claim/reconcile/settle
    /// pipeline <see cref="Toolbar"/> uses, entered from a third call site
    /// (<c>IGanttStateHost.SetViewModeAsync</c>) instead of a new one. Treated
    /// exactly like <see cref="Toolbar"/> for the controlled-consumer echo
    /// (<c>SettleViewModeIntentAsync</c>'s <c>owesConsumerEcho</c>): an imperative
    /// pick against a CONTROLLED chart still asks the parent to ratify it, same as a
    /// user's own toolbar click would — the two are indistinguishable from the
    /// parent's point of view (both are "the component decided a new mode"), only
    /// the trigger differs, which this member exists purely to record for
    /// clarity/audit, not to branch on anywhere else.
    /// </summary>
    Imperative,

    /// <summary>
    /// A Ctrl/Cmd+wheel zoom gesture over the timeline (<c>GanttTimeline.WheelZoom</c>).
    /// Treated exactly like <see cref="Toolbar"/>/<see cref="Imperative"/> for the
    /// controlled-consumer echo — a user zooming by wheel is just as much "the
    /// component decided a new mode" as a toolbar click, so a controlled chart is
    /// asked to ratify it the same way. The one thing that DOES differ for this
    /// source: <c>GanttChart.HandleWheelZoomRequestedAsync</c> supplies an explicit,
    /// already-known anchor (date + pointer offset) instead of letting
    /// <c>ReconcileAsync</c> capture the live viewport CENTER — see
    /// <c>ReconcileAsync</c>'s own <c>explicitCapturedCenter</c>/<c>explicitOffsetOverride</c>
    /// parameters.
    /// </summary>
    Wheel,
}

/// <summary>
/// How far the owning view-mode intent has progressed. An intent owns the view
/// mode from the moment it is claimed until it reaches <see cref="Settled"/> —
/// that window, not "did some reconcile commit", is what a replay must respect.
/// </summary>
internal enum GanttViewModePhase
{
    /// <summary>Claimed but not yet committed to <c>GanttState</c> — a reconcile for it is in flight, or the pass carrying it was superseded and is waiting to be replayed.</summary>
    Applying,

    /// <summary>Committed to <c>GanttState</c>, but the two-way <c>ViewModeChanged</c> echo for it has not come back yet, so the parent's <c>ViewMode</c> parameter may still hold the pre-pick value.</summary>
    Notifying,

    /// <summary>Committed and acknowledged. Nothing about this intent is outstanding, and <c>GanttState.ViewMode</c> equals its <see cref="GanttViewModeIntent.Mode"/>.</summary>
    Settled,
}

/// <summary>
/// The single representation of "which intent currently owns the GanttV3 view
/// mode, on whose authority, and for how long" (Codex PR-382 review round 3).
/// </summary>
/// <remarks>
/// Replaces the four independently-maintained discriminators rounds 17-20
/// accreted in <c>GanttChart</c> — <c>_pendingToolbarMode</c>,
/// <c>_committedViewModeParam</c>, <c>_lastSeenViewModeParam</c> and the
/// <c>MarkViewModeParamAccountedFor</c> helper that tried to keep the last two in
/// step. Each of those carried ONE fragment of the ownership question and had its
/// OWN hand-maintained lifetime, written at a different call site; every review
/// round corrected one of those lifetimes and exposed the next.
///
/// The whole question is answered here instead, by four facts that are only ever
/// written together:
/// <list type="bullet">
/// <item><see cref="Mode"/> — what the owner wants.</item>
/// <item><see cref="Source"/> — who wants it (which also decides whether a
/// commit owes the consumer a <c>ViewModeChanged</c> echo: only a
/// <see cref="GanttViewModeSource.Toolbar"/> pick does).</item>
/// <item><see cref="Phase"/> — how far it has got, i.e. whether it is still
/// pending. A replay uses <see cref="Mode"/> exactly while
/// <see cref="IsPending"/> is true, so an intent survives an arbitrarily long
/// consumer callback.</item>
/// <item><see cref="ParamAccountedFor"/> — the <c>ViewMode</c> PARAMETER value
/// this intent has already folded in. "Has the parameter been accounted for" is
/// therefore a property OF the owner, not a separate field someone has to
/// remember to advance: claiming an intent records it, and settling one advances
/// it to whatever the parent should now be holding.</item>
/// </list>
/// <see cref="Id"/> is the intent's stable identity — bumped only when a NEW
/// intent is claimed, never by a replay. A pass that started an intent's consumer
/// callback compares it on resume, so a callback that outlives its intent (because
/// a newer pick of ANY source took over meanwhile) can never settle, clear or
/// clobber the newer one.
/// </remarks>
/// <param name="Id">Stable identity — see the remarks.</param>
/// <param name="Mode">The view mode this intent resolves to.</param>
/// <param name="Source">Which trigger authored it.</param>
/// <param name="Phase">How far it has progressed.</param>
/// <param name="ParamAccountedFor">The <c>ViewMode</c> parameter value already folded into this intent.</param>
/// <param name="AccountedWhileControlled">Whether <c>ViewModeChanged</c> had a
/// delegate when <see cref="ParamAccountedFor"/> was recorded. Part of the same
/// accounting, because the parameter's AUTHORITY — not just its value — is what
/// is being accounted for: an uncontrolled chart may legitimately hold a toolbar
/// mode its parameter never carried, but the moment a consumer opts INTO control
/// its parameter becomes authoritative again, so that transition is itself a new
/// assertion even when the value is unchanged (Codex PR-382 review round 6,
/// "Reconcile when the binding becomes controlled").</param>
/// <param name="ParamRedeliveredWhileNotifying">Whether the parent delivered a
/// parameter pass while this intent was <see cref="GanttViewModePhase.Notifying"/>
/// WITHOUT that pass authoring an intent of its own — i.e. the consumer re-pushed
/// the <c>ViewMode</c> this intent had already accounted for. That re-delivery is
/// the parent's answer to the pick, and it is what
/// <see cref="GanttViewModePhase.Notifying"/>'s exit condition consults: see
/// <c>GanttChart.SettleViewModeIntentAsync</c> (Codex PR-382 review round 5,
/// "Preserve controlled-mode rejections during callback renders").</param>
internal readonly record struct GanttViewModeIntent(
    long Id,
    GanttViewMode Mode,
    GanttViewModeSource Source,
    GanttViewModePhase Phase,
    GanttViewMode ParamAccountedFor,
    bool AccountedWhileControlled,
    bool ParamRedeliveredWhileNotifying = false)
{
    /// <summary>
    /// True while this intent still owns the view mode outright — i.e. anything
    /// that supersedes the pass carrying it must replay <see cref="Mode"/>
    /// rather than re-deriving a mode from the parameter.
    /// </summary>
    public bool IsPending => Phase != GanttViewModePhase.Settled;
}

/// <summary>What date the one-shot scroll intent targets for a pass.</summary>
internal enum GanttScrollTarget
{
    /// <summary>No scroll intent is emitted — the DOM keeps its current position.</summary>
    None,

    /// <summary>The captured live-scroll center (preserve what the user was looking at). Requires a capture.</summary>
    CapturedCenter,

    /// <summary>An emptiness transition: Today when it falls inside the new range, else the new range's own midpoint.</summary>
    TodayOrMidpoint,
}

/// <summary>The outcome of one snapshot diff.</summary>
/// <param name="NeedsLiveCenterCapture">True when the pass must read the pane's live
/// scroll center (under the OLD geometry) before committing anything — i.e. whenever
/// <see cref="Target"/> is <see cref="GanttScrollTarget.CapturedCenter"/> or the range
/// self-centers on that capture.</param>
/// <param name="Range">Where the reconciled <c>VisibleRange</c> comes from.</param>
/// <param name="Target">What the one-shot scroll intent targets.</param>
internal readonly record struct GanttViewportDecision(
    bool NeedsLiveCenterCapture,
    GanttRangeSource Range,
    GanttScrollTarget Target)
{
    /// <summary>
    /// True when nothing in the diff changed at all, so the pass has no viewport
    /// work to do. Provably equivalent to "prev and next are field-for-field
    /// identical": <see cref="GanttViewportReconciler.Decide"/> forces
    /// <see cref="GanttRangeSource.TaskDerived"/> for any task change and
    /// <see cref="GanttRangeSource.SelfCenteredOnCapture"/> for any mode change,
    /// and any geometry change forces a <see cref="GanttScrollTarget"/> other
    /// than <see cref="GanttScrollTarget.None"/>.
    /// </summary>
    public bool IsNoOp => Range == GanttRangeSource.Keep && Target == GanttScrollTarget.None;
}

/// <summary>Shared geometry helpers for the GanttV3 viewport reconcile.</summary>
internal static class GanttViewportGeometry
{
    /// <summary>
    /// The timeline's leading offset for a given (tree-pane, direction, tree-pane-width)
    /// triple. Only LTR-with-tree adds the tree's width before the timeline's origin —
    /// under RTL the outer flex row reverses, so the timeline already sits at the
    /// content's physical-left origin (see <c>GanttChart.ScrollHostLeadingOffset</c>'s
    /// remarks). <paramref name="treePaneWidth"/> is the LIVE combined width (design
    /// spec Phase 3, T5 — name column + any <c>GanttTreeColumn</c>s), not the old fixed
    /// <c>GanttScale.DefaultTreePaneWidth</c> constant — see <see cref="GanttViewportSnapshot.TreePaneWidth"/>'s
    /// own remarks for why a splitter resize must feed this the same way ColumnWidth/
    /// ShowTreePane already do.
    /// </summary>
    public static double LeadingOffset(bool showTreePane, LayoutDirection direction, double treePaneWidth) =>
        showTreePane && direction == LayoutDirection.Ltr ? treePaneWidth : 0;
}

/// <summary>
/// The single owner of GanttV3 viewport intent (Codex round 14 consolidation).
/// Pure decision logic: given the previous and current <see cref="GanttViewportSnapshot"/>,
/// <see cref="Decide"/> returns exactly how the range and the (one-shot) scroll
/// intent must move — the whole "tasksChanged × viewModeChanged × emptiness ×
/// geometry" matrix that rounds 11-13 grew across three separate methods, derived
/// here from ONE diff instead of scattered per-parameter flags. Stateless and free
/// of any Blazor/DOM dependency, so the matrix is unit-testable directly on
/// snapshot pairs (mirrors how <c>GanttScale</c>/<c>GanttState</c> were built).
///
/// <c>GanttChart</c> owns the execution around a decision: capture the live center
/// (when required) under the OLD geometry BEFORE committing anything, then commit
/// tasks/mode/range synchronously (one coherent frame — Codex round 14, finding
/// #4), then emit the one-shot scroll intent.
/// </summary>
internal static class GanttViewportReconciler
{
    /// <summary>
    /// Decides how the viewport reconciles from <paramref name="prev"/> to
    /// <paramref name="next"/>. The matrix, derived from the two snapshots plus
    /// <paramref name="taskRangeDisjoint"/>:
    ///
    /// <code>
    /// tasksChanged | viewModeChanged | range                | target
    /// ------------ | --------------- | -------------------- | -----------------------------------------
    /// true         | (either)        | TaskDerived          | emptiness transition ? TodayOrMidpoint
    ///              |                 |                      |   : (mode/geometry changed ? CapturedCenter
    ///              |                 |                      |   : (disjoint range ? TodayOrMidpoint : None))
    /// false        | true            | SelfCenteredOnCapture| CapturedCenter
    /// false        | false           | Keep                 | geometry changed ? CapturedCenter : None
    /// </code>
    ///
    /// "geometry changed" = any of tree-pane / direction / column-width moved. A
    /// pure geometry change never rebuilds the range (only the scroll target moves);
    /// a genuine mode switch reshapes it around the captured center; a task-set
    /// change re-derives it from the new tasks. An emptiness transition (renderable
    /// empty ⇄ populated) always wins the target, since preserving a live center
    /// across it is meaningless.
    ///
    /// <paramref name="taskRangeDisjoint"/> (Codex round 16, finding #4) only
    /// matters in the "nothing else changed" corner: a PLAIN task replacement
    /// (viewMode/geometry both unchanged) whose new task-derived range doesn't
    /// overlap the range currently in effect at all used to leave the DOM's own
    /// untouched scroll position in place under None — meaningless once the range
    /// becomes disjoint from it, landing on empty space unrelated to either the
    /// old or the new tasks. Deliberately does NOT override the mode/geometry-
    /// changed branch above: a tasksChanged+viewModeChanged combination (round
    /// 12/14's own case 4 — an async-loaded task swap arriving together with a
    /// mode switch) keeps preserving the captured center even across a disjoint
    /// replacement, by design — it never resets to Today just because the new
    /// tasks happen to be far away.
    /// </summary>
    /// <param name="taskRangeDisjoint">True when <paramref name="prev"/> and
    /// <paramref name="next"/> both have tasks (no emptiness transition) but the
    /// newly task-derived date range doesn't overlap the range currently in effect
    /// at all — computed by the caller from actual date data, which this snapshot
    /// type deliberately doesn't carry (see its own remarks: everything here reduces
    /// to plain diffable facts, not full range state) so this decision stays a pure
    /// function of simple, cheaply-computed inputs.</param>
    public static GanttViewportDecision Decide(GanttViewportSnapshot prev, GanttViewportSnapshot next, bool taskRangeDisjoint)
    {
        var tasksChanged = next.TasksVersion != prev.TasksVersion;
        var viewModeChanged = next.ViewMode != prev.ViewMode;
        var geometryChanged =
            next.ColumnWidth != prev.ColumnWidth ||
            next.ShowTreePane != prev.ShowTreePane ||
            next.Direction != prev.Direction ||
            // Design spec Phase 3, T5 — a splitter resize changes how many
            // pixels of tree pane precede the timeline's own origin (see
            // GanttViewportSnapshot.TreePaneWidth's own remarks). GanttChart's
            // splitter-commit path keeps this snapshot field in sync directly
            // (no scroll intent — see GanttChart.HandleTreePaneResizeAsync), so this
            // branch is belt-and-braces: it only actually fires if some OTHER
            // pass reaches Decide with a stale TreePaneWidth still on `prev`.
            next.TreePaneWidth != prev.TreePaneWidth;
        var emptinessTransition = next.RenderableEmpty != prev.RenderableEmpty;

        GanttRangeSource range;
        GanttScrollTarget target;

        if (tasksChanged)
        {
            // A new task set always re-derives the range from the new tasks'
            // own min/max (mirrors v2, which never keeps a stale window across
            // a task-set change). The target then depends on emptiness first,
            // else on whether the user's live center is worth preserving.
            //
            // taskRangeDisjoint (round 16 finding #4) ONLY overrides the
            // "nothing else changed" None branch — a tasksChanged+viewModeChanged
            // (or +geometryChanged) combination deliberately keeps preserving the
            // captured center even across a disjoint task-range replacement (round
            // 12/14's own case-4 behavior: an async-loaded task swap arriving
            // together with a mode switch preserves continuity with whatever the
            // user was looking at, never resets to Today just because the new
            // tasks happen to be far away). The dispatch's own finding is scoped
            // to the "with unchanged params" case specifically — a plain task
            // replacement with NOTHING else changing, where None used to mean "the
            // DOM's own untouched scroll position" (meaningless once the range
            // becomes disjoint from it), not "the captured center."
            range = GanttRangeSource.TaskDerived;
            target = emptinessTransition
                ? GanttScrollTarget.TodayOrMidpoint
                : (viewModeChanged || geometryChanged)
                    ? GanttScrollTarget.CapturedCenter
                    : (taskRangeDisjoint ? GanttScrollTarget.TodayOrMidpoint : GanttScrollTarget.None);
        }
        else if (viewModeChanged)
        {
            // A genuine mode switch with no task change reshapes the range
            // (new unit/column width) around whatever the user was looking at.
            range = GanttRangeSource.SelfCenteredOnCapture;
            target = GanttScrollTarget.CapturedCenter;
        }
        else
        {
            // No task or mode change. A tree-pane/direction/column-width change
            // moves only the scroll target — the date RANGE itself is unaffected.
            range = GanttRangeSource.Keep;
            target = geometryChanged ? GanttScrollTarget.CapturedCenter : GanttScrollTarget.None;
        }

        return new GanttViewportDecision(
            NeedsLiveCenterCapture: target == GanttScrollTarget.CapturedCenter,
            Range: range,
            Target: target);
    }
}

@namespace Lumeo
@using System.ComponentModel
@using Lumeo.GanttV3
@inject Lumeo.Services.Localization.ILumeoLocalizer L
@attribute [EditorBrowsable(EditorBrowsableState.Never)]

@* GanttZoomControl — the floating +/- zoom stepper (design spec Phase 3, T7
   — "Floating zoom control (+/- overlay in the canvas corner) in addition to
   the toolbar switcher"). Purely presentational and unpositioned (no
   absolute/sticky classes of its own) — the caller (GanttTimeline) owns
   WHERE it sits in the canvas corner, this component only owns "which two
   buttons, in what enabled state, stepping through which levels". Steps
   through the SAME resolved zoom-level list GanttNav's own toolbar switcher
   uses (GanttZoomLevelModel — shared, not duplicated, see that type's own
   remarks) so the two surfaces can never silently disagree about what's
   reachable.

   NOTE (accessibility): see GanttBar.razor's identical NOTE — the Razor
   compiler always generates a component's class as `public`, so despite the
   design intent of `internal`, this stays `public` with its members recorded
   in PublicAPI.Unshipped.txt. [EditorBrowsable(Never)] keeps it out of
   consumer IntelliSense until the Phase-4 rename. *@
<div class="@RootClass" @attributes="AdditionalAttributes">
    <Button Variant="Button.ButtonVariant.Ghost" Size="Button.ButtonSize.Icon"
            aria-label="@L["Gantt.ZoomOut"]" Disabled="@(!CanZoomOut)"
            OnClick="HandleZoomOutAsync">
        <SvgGlyph Svg="@(LumeoIcons.Minus)" class="h-3.5 w-3.5" />
    </Button>
    <Button Variant="Button.ButtonVariant.Ghost" Size="Button.ButtonSize.Icon"
            aria-label="@L["Gantt.ZoomIn"]" Disabled="@(!CanZoomIn)"
            OnClick="HandleZoomInAsync">
        <SvgGlyph Svg="@(LumeoIcons.Plus)" class="h-3.5 w-3.5" />
    </Button>
</div>

@code {
    /// <summary>The active zoom level.</summary>
    [Parameter, EditorRequired] public GanttViewMode ViewMode { get; set; } = GanttViewMode.Day;

    /// <summary>Raised when +/- steps to a new zoom level.</summary>
    [Parameter] public EventCallback<GanttViewMode> ViewModeChanged { get; set; }

    /// <summary>Restricts/orders which levels +/- steps through — same contract as <c>GanttNav.ZoomLevels</c> (see <see cref="GanttZoomLevelModel"/>).</summary>
    [Parameter] public IReadOnlyList<GanttViewMode>? ZoomLevels { get; set; }

    /// <summary>Additional CSS classes merged onto the root element.</summary>
    [Parameter] public string? Class { get; set; }

    /// <summary>Captures unmatched attributes and applies them to the root element.</summary>
    [Parameter(CaptureUnmatchedValues = true)] public Dictionary<string, object>? AdditionalAttributes { get; set; }

    private string RootClass => Cx.Merge(
        "lumeo-gantt-v3-zoom-control inline-flex items-center gap-0.5 rounded-md border border-border/60 bg-card p-0.5 shadow-md",
        Class);

    private IReadOnlyList<GanttViewMode> ResolvedLevels => GanttZoomLevelModel.Resolve(ZoomLevels);

    // -1 when ViewMode isn't among the resolved levels at all (e.g. a
    // sub-day mode, or a ZoomLevels list that excludes the chart's current
    // mode) — both buttons disable in that case (see CanZoomIn/CanZoomOut)
    // rather than guessing which direction to jump from an unknown position.
    private int CurrentIndex
    {
        get
        {
            var levels = ResolvedLevels;
            for (var i = 0; i < levels.Count; i++)
            {
                if (levels[i] == ViewMode) return i;
            }
            return -1;
        }
    }

    // DefaultLevels/RepresentableLevels are ordered coarsest-last (Day..Year
    // — GanttZoomLevelModel's own order, matching GanttNav's toolbar left-to-
    // right layout): "+" (zoom IN, more detail) steps TOWARD index 0; "-"
    // (zoom OUT, less detail) steps TOWARD the last index.
    private bool CanZoomIn => CurrentIndex > 0;
    private bool CanZoomOut => CurrentIndex >= 0 && CurrentIndex < ResolvedLevels.Count - 1;

    private Task HandleZoomInAsync() => CanZoomIn ? StepToAsync(CurrentIndex - 1) : Task.CompletedTask;
    private Task HandleZoomOutAsync() => CanZoomOut ? StepToAsync(CurrentIndex + 1) : Task.CompletedTask;

    private Task StepToAsync(int index)
    {
        var mode = ResolvedLevels[index];
        return mode == ViewMode || !ViewModeChanged.HasDelegate ? Task.CompletedTask : ViewModeChanged.InvokeAsync(mode);
    }
}

namespace Lumeo.GanttV3;

/// <summary>
/// Pure, static "which zoom levels are toolbar/zoom-control-representable, in
/// what order" logic — shared by <see cref="Lumeo.GanttNav"/>'s toggle group
/// and <see cref="Lumeo.GanttZoomControl"/>'s +/- stepper (design spec Phase
/// 3, T7 — "Floating zoom control ... steps through the active ZoomLevels
/// list"). Extracted from <see cref="Lumeo.GanttNav"/>'s own former private
/// members (a pure "extract method" refactor — <see cref="Lumeo.GanttNav"/>'s
/// EXTERNALLY observable behavior is unchanged, verified against its own
/// existing test suite) so the toolbar and the floating control can never
/// silently diverge on "what counts as a representable mode" the way two
/// independently-hand-maintained copies of the same list eventually would
/// (e.g. a future 6th <see cref="GanttViewMode"/> added to one list and
/// forgotten in the other).
/// </summary>
internal static class GanttZoomLevelModel
{
    /// <summary>
    /// The toolbar/zoom-control's DEFAULT set (no <c>ZoomLevels</c> parameter
    /// supplied) — v2 parity (same v2's <c>Gantt.razor</c> ZoomLevels default
    /// contract). Deliberately excludes <see cref="GanttViewMode.Quarter"/>
    /// (design spec Phase 3, T2) — see <see cref="RepresentableLevels"/>'s own
    /// remarks for why.
    /// </summary>
    internal static readonly IReadOnlyList<GanttViewMode> DefaultLevels =
    [
        GanttViewMode.Day, GanttViewMode.Week, GanttViewMode.Month, GanttViewMode.Year,
    ];

    /// <summary>
    /// Every zoom level with its OWN toolbar-representable label — used to
    /// FILTER a caller-supplied <c>ZoomLevels</c> list (design spec Phase 3,
    /// T2 — adding <see cref="GanttViewMode.Quarter"/> as a 5th DEFAULT
    /// toolbar button would silently change every existing v3 chart's
    /// default look/visual-snapshot baselines with no explicit opt-in; a
    /// consumer wanting Quarter reachable passes it in their OWN
    /// <c>ZoomLevels</c> list instead, which this set (not
    /// <see cref="DefaultLevels"/>) now allows through).
    /// </summary>
    internal static readonly IReadOnlyList<GanttViewMode> RepresentableLevels =
    [
        GanttViewMode.Day, GanttViewMode.Week, GanttViewMode.Month, GanttViewMode.Quarter, GanttViewMode.Year,
    ];

    /// <summary>
    /// The zoom levels a caller-supplied <c>ZoomLevels</c> parameter actually
    /// resolves to: the representable subset of <paramref name="zoomLevels"/>
    /// (in the CALLER's own order) when non-empty, else <see cref="DefaultLevels"/>.
    /// </summary>
    internal static IReadOnlyList<GanttViewMode> Resolve(IReadOnlyList<GanttViewMode>? zoomLevels) =>
        zoomLevels is { Count: > 0 }
            ? zoomLevels.Where(l => RepresentableLevels.Contains(l)).ToList()
            : DefaultLevels;

    /// <summary>The localization key for a representable zoom level's own label.</summary>
    internal static string LabelKey(GanttViewMode level) => level switch
    {
        GanttViewMode.Day => "Gantt.Day",
        GanttViewMode.Week => "Gantt.Week",
        GanttViewMode.Month => "Gantt.Month",
        GanttViewMode.Quarter => "Gantt.Quarter",
        GanttViewMode.Year => "Gantt.Year",
        _ => "Gantt.Day",
    };
}
